// Step 1: Extract User ID & Log Workflow Start
const input = $input.first().json;
const body = input.body || input;
const user_id = body.user_id || body.event?.user_id;

if (!user_id) {
  console.error("[n8n Orchestrator] [ERROR] Missing user_id in trigger payload.");
  throw new Error("Missing user_id in trigger request");
}

console.log(`[n8n Orchestrator] [START] Workflow initiated for user_id: ${user_id} at ${new Date().toISOString()}`);

return [{
  json: {
    user_id: user_id,
    triggered_at: new Date().toISOString()
  }
}];

// Step 4: Evaluate Incremental Event Metrics & Threshold
const userId = $('Log Workflow Start').first().json.user_id;

// MongoDB Group Aggregation result
const aggItems = $('Count & Get Latest Event Timestamp').all();
const aggData = aggItems.length > 0 ? aggItems[0].json : {};
const totalEvents = aggData.total_events || 0;
const latestTimestamp = aggData.latest_timestamp || new Date().toISOString();

// Behavior Profile metadata
const profileItems = $('Get Behavior Profile Metadata').all();
const profileData = profileItems.length > 0 ? profileItems[0].json : {};
const lastProcessedCount = profileData.last_processed_event_count || 0;
const lastProcessedTimestamp = profileData.last_processed_timestamp || "1970-01-01T00:00:00.000Z";

const thresholdMet = totalEvents >= 100;
const hasNewEvents = totalEvents > lastProcessedCount || latestTimestamp > lastProcessedTimestamp;
const shouldProcess = thresholdMet && hasNewEvents;

console.log(`[n8n Orchestrator] [EVALUATE] User: ${userId} | Total Events: ${totalEvents} | Last Processed Count: ${lastProcessedCount} | Latest TS: ${latestTimestamp} | Last TS: ${lastProcessedTimestamp} | Action: ${shouldProcess ? 'PROCEED_TO_FASTAPI' : 'SKIP'}`);

return [{
  json: {
    user_id: userId,
    total_events: totalEvents,
    last_processed_count: lastProcessedCount,
    latest_timestamp: latestTimestamp,
    last_processed_timestamp: lastProcessedTimestamp,
    threshold_met: thresholdMet,
    has_new_events: hasNewEvents,
    should_process: shouldProcess,
    evaluated_at: new Date().toISOString()
  }
}];

// Step 6: Log Threshold Met & Dispatch Request
const data = $input.first().json;
console.log(`[n8n Orchestrator] [DISPATCH] Threshold reached (${data.total_events} events). Dispatching POST to FastAPI /process-data for user_id: ${data.user_id}`);

return [{
  json: {
    user_id: data.user_id,
    total_events: data.total_events,
    latest_timestamp: data.latest_timestamp,
    dispatched_at: new Date().toISOString()
  }
}];

// Step 8: Capture and Log FastAPI Response
const resItem = $input.first().json;
const evalContext = $('Evaluate Incremental Metrics').first().json;

// Extract status code and body safely
const statusCode = resItem.statusCode || resItem.status || (resItem.body ? 200 : 500);
const body = resItem.body || resItem;
const isSuccess = statusCode >= 200 && statusCode < 300;

console.log(`[n8n Orchestrator] [RESPONSE] FastAPI returned HTTP ${statusCode} for user_id: ${evalContext.user_id}. Success: ${isSuccess}`);
if (!isSuccess) {
  console.error(`[n8n Orchestrator] [ERROR_DETAIL] FastAPI Response:`, JSON.stringify(body));
}

return [{
  json: {
    user_id: evalContext.user_id,
    http_status: statusCode,
    is_success: isSuccess,
    total_events: evalContext.total_events,
    latest_timestamp: evalContext.latest_timestamp,
    backend_response: body,
    evaluated_at: new Date().toISOString()
  }
}];

// Step 11: Validate MongoDB Metadata Update Success
const mongoResult = $input.first().json;
const parentContext = $('Log & Parse FastAPI Response').first().json;

const isUpdateValid = mongoResult !== null && mongoResult !== undefined;

console.log(`[n8n Orchestrator] [SUCCESS] Pipeline execution finished cleanly for user_id: ${parentContext.user_id}. Metadata updated.`);

return [{
  json: {
    status: "success",
    user_id: parentContext.user_id,
    processed_event_count: parentContext.total_events,
    last_processed_timestamp: parentContext.latest_timestamp,
    pipeline_status: "completed",
    pipeline_version: "v1",
    completed_at: new Date().toISOString(),
    backend_response: parentContext.backend_response
  }
}];
